def fetch_all_products_with_images() -> list:
    """Fetch all products that have at least one image."""
    products, page_info = [], None
    while True:
        params = {
            "limit": 250,
            "fields": "id,title,handle,product_type,variants,images,vendor",
        }
        if page_info:
            params["page_info"] = page_info
        r = _req("get", f"{BASE}/products.json", params=params)
        r.raise_for_status()
        batch = r.json().get("products", [])
        products.extend([p for p in batch if p.get("images")]) # Only add products with images
        link = r.headers.get("Link", "")
        m = re.search(r'<[^>]*page_info=([^&>]+)[^>]*>;\s*rel="next"', link)
        if m:
            page_info = m.group(1)
        else:
            break
    return products

def fetch_all_articles_with_blog_info(article_id: int | None = None) -> list:
    """
    Fetches all articles from all blogs, attaching blog_id and blog_handle.
    If article_id is provided, fetches only that specific article.
    """
    all_blogs = get_all_blogs()
    all_articles = []

    for blog in all_blogs:
        blog_id = blog["id"]
        blog_handle = blog["handle"]
        
        if article_id:
            # Fetch specific article
            try:
                r = _req("get", f"{BASE}/blogs/{blog_id}/articles/{article_id}.json")
                r.raise_for_status()
                article = r.json().get("article")
                if article:
                    article["_blog_id"] = blog_id
                    article["_blog_handle"] = blog_handle
                    all_articles.append(article)
                    return all_articles # Found the article, return it
            except requests.exceptions.HTTPError as e:
                if e.response.status_code == 404:
                    continue # Article not in this blog, try next
                raise
        else:
            # Fetch all articles for this blog
            page_info = None
            while True:
                params = {"limit": 250, "fields": "id,title,handle,body_html,image,tags,summary_html,published_at,author"}
                if page_info:
                    params["page_info"] = page_info
                r = _req("get", f"{BASE}/blogs/{blog_id}/articles.json", params=params)
                r.raise_for_status()
                batch = r.json().get("articles", [])
                if not batch:
                    break
                for article in batch:
                    article["_blog_id"] = blog_id
                    article["_blog_handle"] = blog_handle
                    all_articles.append(article)
                link = r.headers.get("Link", "")
                m = re.search(r'<[^>]*page_info=([^&>]+)[^>]*>;\s*rel="next"', link)
                if m:
                    page_info = m.group(1)
                else:
                    break
    return all_articles

def create_redirect(old_full_url: str, new_full_url: str, dry_run: bool) -> bool:
    """
    Creates a 301 redirect from old_full_url to new_full_url.
    Checks if redirect already exists to prevent duplicates.
    """
    # Extract path from full URLs
    old_path = urlparse(old_full_url).path
    new_target = new_full_url # Shopify redirect target can be a full URL

    # Check for existing redirect
    try:
        r = _req("get", f"{BASE}/redirects.json?path={quote(old_path)}")
        r.raise_for_status()
        existing_redirects = r.json().get("redirects", [])
        for redirect in existing_redirects:
            if redirect["path"] == old_path and redirect["target"] == new_target:
                print(f"    [Redirect] Existing redirect found for '{old_path}' -> '{new_target}'. Skipping.")
                return False
    except Exception as e:
        print(f"    [Redirect] Error checking existing redirects for path '{old_path}': {e}")
        # Continue to attempt creation if check fails

    if dry_run:
        print(f"    [DRY-RUN] Would create redirect: '{old_path}' -> '{new_target}'")
        return True

    try:
        payload = {
            "redirect": {
                "path": old_path,
                "target": new_target
            }
        }
        r = _req("post", f"{BASE}/redirects.json", json=payload)
        r.raise_for_status()
        print(f"    [Redirect] Created redirect: '{old_path}' -> '{new_target}'")
        return True
    except Exception as e:
        print(f"    [Redirect] Failed to create redirect for '{old_path}' -> '{new_target}': {e}")
        return False

def regenerate_single_article(
    original_article: dict,
    all_products_with_images: list,
    all_blogs: list,
    dry_run: bool,
    force_format: str | None = None
) -> dict:
    """
    Regenerates content for a single article, handles redirects, and updates Shopify.
    Returns a dictionary with status and details.
    """
    blog_id = original_article["_blog_id"]
    blog_handle = original_article["_blog_handle"]
    article_id = original_article["id"]
    original_title = original_article["title"]
    original_handle = original_article["handle"]
    original_tags = original_article.get("tags", "")
    
    log_entry = {
        "article_id": article_id,
        "original_title": original_title,
        "original_handle": original_handle,
        "status": "skipped",
        "changes": []
    }

    print(f"\nProcessing article: '{original_title}' (ID: {article_id}, Handle: {original_handle})")

    # 1. Select a relevant product for the article
    # Try to pick a product whose type or title keywords match the article title
    product_pool_for_selection = [p for p in all_products_with_images if p.get("images")]
    if not product_pool_for_selection:
        print("  [ERROR] No products with images available for selection. Skipping article.")
        log_entry["status"] = "error"
        log_entry["message"] = "No products with images for regeneration"
        return log_entry

    selected_product = None
    # Attempt to find a product whose type matches the article title
    for ptype_keyword in ["jean", "dress", "skirt", "top", "pant", "jacket", "coat", "sweater", "cardigan", "swimwear", "activewear", "accessory"]:
        if ptype_keyword in original_title.lower():
            matching_products = [p for p in product_pool_for_selection if ptype_keyword in (p.get("product_type") or "").lower()]
            if matching_products:
                selected_product = random.choice(matching_products)
                break
    
    if not selected_product:
        # Fallback: pick a random product from the pool
        selected_product = random.choice(product_pool_for_selection)

    print(f"  Selected product for regeneration: '{selected_product['title']}' (Type: {selected_product.get('product_type')})")

    # 2. Generate keyword, title hint, and format
    keyword, title_hint, fmt = generate_keyword_title_and_format(selected_product, format_override=force_format)
    print(f"  Generated format: {fmt} | Keyword: '{keyword}' | Title Hint: '{title_hint}'")

    # 3. Select styling matches for collage and prompt
    matching_products = select_styling_matches(selected_product, all_products_with_images, num_matches=2)
    print(f"  Matching products for collage: {[p['title'] for p in matching_products]}")

    # 4. Build AI prompt and generate content
    prompt, _ = _build_prompt(fmt, selected_product, keyword, title_hint, similar_products=all_products_with_images, matching_products=matching_products)
    print("  Generating new content with AI...")
    raw_ai_response = ai_client.generate(prompt, max_tokens=2000, temperature=0.75)

    if not raw_ai_response:
        print("  [ERROR] AI content generation failed. Skipping article.")
        log_entry["status"] = "error"
        log_entry["message"] = "AI content generation failed"
        return log_entry

    html_body = _clean_html(raw_ai_response)
    seo_meta = parse_and_clean_seo_meta(raw_ai_response, keyword, selected_product["title"], get_clean_product_type(selected_product))
    
    new_title = _extract_h1(html_body, seo_meta["seo_title"])
    suggested_handle = seo_meta["suggested_handle"]
    
    # Ensure suggested_handle is not empty
    if not suggested_handle:
        suggested_handle = _slugify(new_title)
        seo_meta["suggested_handle"] = suggested_handle

    # 5. Generate and upload featured image collage
    img_url = None
    collage_path = generate_outfit_collage(selected_product, matching_products)
    if collage_path and collage_path.exists():
        if not dry_run:
            ts = int(time.time())
            filename = f"regenerated_collage_{article_id}_{ts}.jpg"
            img_url = upload_image_to_shopify(collage_path, filename)
            try:
                collage_path.unlink()
            except Exception:
                pass
        else:
            img_url = f"file:///{collage_path.absolute().as_posix()}"
    if not img_url:
        print("  [WARN] Collage creation/upload failed, falling back to single product image URL.")
        img_url = product_img_url(selected_product) # Fallback to single product image

    # 6. Inject product cards and related products section
    html_body = inject_product_card(html_body, selected_product, keyword)
    html_body += make_related_products_section(all_products_with_images, selected_product.get("handle", ""), keyword, matching_products)

    # 7. Generate tags
    new_tags = _make_tags(selected_product, fmt, keyword)
    # Merge with original tags, ensuring uniqueness and limit
    original_tags_list = [t.strip() for t in original_tags.split(',') if t.strip()]
    new_tags = list(dict.fromkeys(new_tags + original_tags_list))[:25]

    # 8. Handle comparison and redirect
    final_handle = original_handle
    if suggested_handle != original_handle:
        print(f"  [HANDLE CHANGE] Suggested handle '{suggested_handle}' differs from original '{original_handle}'.")
        old_full_url = f"{STORE_URL}/blogs/{blog_handle}/{original_handle}"
        new_full_url = f"{STORE_URL}/blogs/{blog_handle}/{suggested_handle}" # Assuming blog_handle remains same
        if not dry_run:
            if create_redirect(old_full_url, new_full_url, dry_run=False):
                final_handle = suggested_handle
                log_entry["changes"].append({"field": "handle", "old": original_handle, "new": suggested_handle, "redirect_created": True})
            else:
                print(f"    [WARN] Failed to create redirect. Keeping original handle: '{original_handle}'.")
                log_entry["changes"].append({"field": "handle", "old": original_handle, "new": original_handle, "redirect_created": False, "message": "Redirect failed"})
        else:
            print(f"    [DRY-RUN] Would change handle to '{suggested_handle}' and create redirect from '{old_full_url}' to '{new_full_url}'.")
            final_handle = suggested_handle # For dry-run output
            log_entry["changes"].append({"field": "handle", "old": original_handle, "new": suggested_handle, "redirect_created": True, "dry_run": True})
    else:
        print(f"  [HANDLE] Handle remains unchanged: '{original_handle}'.")

    # 9. Prepare payload for article update
    payload = {
        "title": new_title,
        "author": random.choice(PEN_NAMES), # Assign a new E-E-A-T author
        "body_html": html_body,
        "summary_html": seo_meta["meta_desc"],
        "tags": ", ".join(new_tags),
        "handle": final_handle,
        "published": original_article.get("published", True), # Keep original published status
    }
    if img_url:
        payload["image"] = {
            "src": img_url,
            "alt": seo_meta["img_alt"],
        }
    
    if new_title != original_title:
        log_entry["changes"].append({"field": "title", "old": original_title, "new": new_title})
    if original_article.get("body_html") != html_body:
        log_entry["changes"].append({"field": "body_html", "old_len": len(original_article.get("body_html", "")), "new_len": len(html_body)})
    if original_article.get("image", {}).get("src") != img_url:
        log_entry["changes"].append({"field": "image_src", "old": original_article.get("image", {}).get("src"), "new": img_url})
    if original_article.get("image", {}).get("alt") != seo_meta["img_alt"]:
        log_entry["changes"].append({"field": "image_alt", "old": original_article.get("image", {}).get("alt"), "new": seo_meta["img_alt"]})
    if original_article.get("tags") != payload["tags"]:
        log_entry["changes"].append({"field": "tags", "old": original_tags, "new": payload["tags"]})
    if original_article.get("author") != payload["author"]:
        log_entry["changes"].append({"field": "author", "old": original_article.get("author"), "new": payload["author"]})

    # 10. Perform update
    if dry_run:
        print(f"  [DRY-RUN] Would update article {article_id} with new content and metadata.")
        print(f"    New Title: {new_title}")
        print(f"    New Handle: {final_handle}")
        print(f"    New Image: {img_url}")
        print(f"    New Tags: {', '.join(new_tags)}")
        log_entry["status"] = "dry_run_success"
    else:
        try:
            # Save a backup of the original article content before we edit it
            backup_data = {
                "article_id": article_id,
                "title": original_title,
                "handle": original_handle,
                "body_html": original_article.get("body_html", ""),
                "summary_html": original_article.get("summary_html", ""),
                "tags": original_tags,
                "image": original_article.get("image", {}),
                "author": original_article.get("author", ""),
                "published_at": original_article.get("published_at", ""),
                "backup_timestamp": datetime.now().isoformat()
            }
            backup_dir = REPO_ROOT / "backup_articles"
            backup_dir.mkdir(exist_ok=True)
            backup_file = backup_dir / f"article_{article_id}_{int(time.time())}.json"
            backup_file.write_text(json.dumps(backup_data, indent=2, ensure_ascii=False), encoding="utf-8")
            print(f"    [Backup] Saved original article content to backup_articles/{backup_file.name}")

            updated_article = _req("put", f"{BASE}/blogs/{blog_id}/articles/{article_id}.json", json={"article": payload}).json().get("article")
            if updated_article:
                print(f"  ✓ Successfully updated article {article_id}.")
                # Set SEO metafields
                set_article_seo_metafields(blog_id, article_id, seo_meta["seo_title"], seo_meta["meta_desc"])
                log_entry["status"] = "success"
            else:
                raise RuntimeError("Shopify update returned no article data.")
        except Exception as e:
            print(f"  [ERROR] Failed to update article {article_id}: {e}")
            log_entry["status"] = "error"
            log_entry["message"] = str(e)
            
    return log_entry

def main():
    parser = argparse.ArgumentParser(description="Regenerate content for existing Shopify blog articles.")
    parser.add_argument("--dry-run", action="store_true", help="Preview changes without writing to Shopify.")
    parser.add_argument("--force", action="store_true", help="Process ALL existing articles.")
    parser.add_argument("--article-id", type=int, default=None, help="Process a single specific article by ID.")
    parser.add_argument("--batch-size", type=int, default=20, help="Number of articles to process per batch in --force mode.")
    parser.add_argument("--batch-index", type=int, default=0, help="0-based index of the batch to process in --force mode.")
    parser.add_argument("--count-only", action="store_true", help="Print total number of articles to process and exit (for CI matrix).")
    parser.add_argument("--force-format", type=str, default=None,
                        choices=FORMATS,
                        help="Force a specific blog format for all regenerated articles.")
    args = parser.parse_args()

    print(f"\n{'='*70}")
    print(f"  MeeeShop Article Regenerator — {datetime.now().strftime('%Y-%m-%d %H:%M')}")
    print(f"  Mode: {'DRY RUN' if args.dry_run else 'LIVE'}")
    print(f"  Scope: {'ALL articles' if args.force else (f'Article ID: {args.article_id}' if args.article_id else 'Default (not implemented yet)')}")
    if args.force:
        print(f"  Batch: {args.batch_index} of size {args.batch_size}")
    if args.force_format:
        print(f"  Forced Format: {args.force_format}")
    print(f"{'='*70}\n")

    all_products_with_images = fetch_all_products_with_images()
    if not all_products_with_images:
        sys.exit("ERROR: No products with images found in Shopify. Cannot regenerate articles.")
    print(f"Loaded {len(all_products_with_images)} products with images for content generation.")

    all_articles = fetch_all_articles_with_blog_info(args.article_id)
    if not all_articles:
        sys.exit("ERROR: No articles found to process.")
    
    if args.count_only:
        print(len(all_articles))
        return

    articles_to_process = []
    if args.article_id:
        articles_to_process = [a for a in all_articles if a["id"] == args.article_id]
        if not articles_to_process:
            sys.exit(f"ERROR: Article with ID {args.article_id} not found.")
    elif args.force:
        start_index = args.batch_index * args.batch_size
        end_index = start_index + args.batch_size
        articles_to_process = all_articles[start_index:end_index]
        print(f"Processing batch {args.batch_index}: articles {start_index} to {end_index-1} out of {len(all_articles)} total.")
    else:
        # Default mode if not --force or --article-id: process a small number of oldest articles
        # For now, let's make it explicit that --force or --article-id is required.
        sys.exit("ERROR: Please specify --force to process all articles or --article-id to process a single article.")

    if not articles_to_process:
        print("No articles selected for processing in this run.")
        return

    results = []
    for article in articles_to_process:
        result = regenerate_single_article(article, all_products_with_images, get_all_blogs(), args.dry_run, args.force_format)
        results.append(result)
        time.sleep(2) # Be kind to APIs

    print(f"\n{'='*70}")
    print("Regeneration Summary:")
    print(f"Total articles attempted: {len(results)}")
    print(f"Successful: {sum(1 for r in results if r['status'] == 'success' or r['status'] == 'dry_run_success')}")
    print(f"Errors: {sum(1 for r in results if r['status'] == 'error')}")
    print(f"{'='*70}\n")

    # Save detailed log
    log_filename = f"regenerate_articles_log_{datetime.now().strftime('%Y%m%d_%H%M%S')}.json"
    with open(LOG_DIR / log_filename, "w", encoding="utf-8") as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
    print(f"Detailed log saved to {LOG_DIR / log_filename}")

if __name__ == "__main__":
    try:
        sys.stdout.reconfigure(encoding="utf-8")
    except Exception:
        pass
    main()